(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.018+t*0.3)*18 + Math.cos(y*0.013-t*0.22)*12;
  const w1y = Math.cos(y*0.02-t*0.28)*18 + Math.sin(x*0.016+t*0.32)*12;
  const w2x = Math.sin((x+y)*0.01+t*0.15)*8;
  const w2y = Math.cos((x-y)*0.012-t*0.18)*8;
  const sx = x+w1x+w2x, sy = y+w1y+w2y;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.07, 2.2],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.09, 1.8],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.055, 2.5],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.11, 1.6],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.065, 2.8],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.08, 2.0],
    [80+Math.sin(t*0.45+3)*110, 40+Math.cos(t*0.65+2)*60, 0.075, 2.3],
    [400+Math.cos(t*0.55+1)*70, 200+Math.sin(t*0.75+4)*50, 0.1, 1.9]
  ];
  let aS=0, iS=0, aS2=0, iS2=0;
  for(const[sX,sY,f,sp]of src){
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    aS+=Math.sin(d*f-t*sp);
    iS+=Math.sin(d*f*0.7+t*sp*0.6+1.5);
    aS2+=Math.cos(d*f*1.3-t*sp*0.8+0.7);
    iS2+=Math.sin(d*f*0.5+t*sp*0.4+2.8);
  }
  const act=aS/8, inh=iS/8, act2=aS2/8, inh2=iS2/8;
  const bg=(Math.sin(sx*0.035+sy*0.022+t*0.7)+Math.sin(sx*0.028-sy*0.038+t*1.0))/2
    +Math.sin((sx+sy)*0.1+t*2.2)*0.25+Math.sin((sx-sy)*0.085-t*1.8)*0.25
    +Math.sin(sx*0.06+sy*0.04+t*1.5)*0.15;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2), ang=Math.atan2(sy-cy,sx-cx);
  const spiral=(Math.sin(dist*0.045-ang*3.5-t*1.4)+Math.sin(dist*0.035+ang*5-t*1.1))*0.35
    +Math.sin(dist*0.08-ang*2-t*2.5)*0.15;
  const vortex=Math.sin(dist*0.06+ang*6-t*0.8)*Math.exp(-dist*0.005)*0.3;
  const lap = (a)=> Math.sin(a*2.5)*0.5;
  const rd1 = Math.tanh((act - inh*0.65 + bg*0.25 + spiral + lap(act)*0.3)*2.0);
  const rd2 = Math.tanh((act2 - inh2*0.6 + bg*0.2 + vortex + lap(inh)*0.25)*1.8);
  const cross = rd1*rd2*1.2;
  const cell=Math.tanh((Math.sin(sx*0.14)*Math.sin(sy*0.14)+Math.sin((sx+sy)*0.09+t)*0.5+Math.sin(sx*0.08-sy*0.11+t*0.7)*0.3)*1.4)*0.25;
  const micro=Math.sin(sx*0.3+t*3)*Math.sin(sy*0.3-t*2.5)*0.08;
  const pulse=0.92+Math.sin(t*0.4)*0.08;
  const blend=(rd1*0.5+rd2*0.3+cross*0.15+cell*0.15+micro)*pulse;
  const v=blend*0.5+0.5;
  const pal=[
    [5,12,45],[10,45,85],[15,90,115],[20,140,130],
    [180,175,60],[220,140,55],[210,90,60],[180,50,55],
    [130,30,60],[70,18,55],[30,12,48],[5,12,45]
  ];
  const idx=v*(pal.length-1), i=Math.min(idx|0,pal.length-2), f=idx-i;
  const reaction=rd1*0.6+rd2*0.4;
  const lum=0.82+Math.sin(reaction*Math.PI)*0.18;
  const edge=Math.abs(reaction)>0.65?1.12:1.0;
  const glow=Math.exp(-Math.abs(reaction)*2)*0.15;
  return[
    Math.min(255,((pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge+glow*60)|0),
    Math.min(255,((pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge+glow*40)|0),
    Math.min(255,((pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge+glow*80)|0)
  ];
}
